    actual: isBstNow ? bstTest.toISOString() : gmtTest.toISOString(),
    detectedOffset: currentOffset,
    expectedLabel: isBstNow ? 'BST (UTC+1)' : 'GMT (UTC+0)',
    details: allOk
      ? `Timezone OK — detected ${isBstNow ? 'BST' : 'GMT'} offset ${currentOffset}`
